var a={name:`Plank`,description:`Menținerea statică a corpului în sprijin pe antebrațe. Antrenează mușchii trunchiului și stabilitatea corpului.`,steps:[`Adoptă sprijinul pe antebrațe, cu coatele sub umeri.`,`Întinde picioarele și aliniază corpul de la călcâie până la cap.`,`Contractă abdomenul și fesierii.`,`Menține poziția timpul stabilit, respirând uniform.`],warnings:[`Oprește exercițiul dacă apare durere la umeri sau în zona lombară.`],techniqueNotes:[`Nu ridica și nu lăsa bazinul.`,`Nu-ți ține respirația.`]};var r={name:`Superman`,description:`Ridicarea simultană a brațelor și picioarelor, culcat pe burtă. Antrenează mușchii spatelui și fesierii.`,steps:[`Culcă-te pe burtă, cu brațele întinse înainte.`,`Ridică simultan puțin brațele, pieptul și picioarele de la podea.`,`Menține 1–2 secunde.`,`Coboară încet.`],warnings:[`Nu te ridica brusc și prea sus.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Privirea în jos, gâtul în linie cu spatele.`,`Mișcă-te lin, fără smucituri.`]};var n={name:`Burpee`,description:`Exercițiu complex: genuflexiune, sprijin culcat, revenire și săritură în sus. Dezvoltă rezistența generală și solicită tot corpul.`,steps:[`Fă o genuflexiune și așază palmele pe podea.`,`Aruncă picioarele înapoi în sprijin culcat.`,`Adu picioarele spre mâini și ridică-te.`,`Fă o săritură mică în sus, cu brațele deasupra capului.`],warnings:[`Aterizează moale și nu arcui zona lombară în sprijin culcat.`,`Oprește exercițiul dacă apare durere la articulații sau în spate.`],techniqueNotes:[`În poziția de sprijin ține corpul drept.`,`Păstrează controlul, nu viteza maximă.`]};var t={"bodyweight-squat":{name:`Genuflexiuni cu greutatea corpului`,description:`Genuflexiunea de bază, fără încărcare. Antrenează cvadricepșii și fesierii și dezvoltă controlul mișcării la genunchi și șolduri.`,steps:[`Stai în picioare, cu tălpile la lățimea umerilor.`,`Împinge șoldurile înapoi și îndoaie genunchii, coborând.`,`Coboară până la o adâncime confortabilă, cu spatele drept.`,`Împinge în tălpi și revino în poziția de start.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Genunchii merg în direcția degetelor de la picioare.`,`Nu ridica călcâiele de pe podea.`]},"split-squat":{name:`Genuflexiuni split`,description:`Genuflexiune în poziție de pas larg. Antrenează separat cvadricepșii și fesierii fiecărui picior și îmbunătățește echilibrul.`,steps:[`Adoptă un pas larg: un picior în față, celălalt în spate.`,`Coboară vertical, îndoind ambii genunchi.`,`Urcă, împingând cu piciorul din față.`,`Fă toate repetările, apoi schimbă piciorul.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Ține trunchiul vertical.`,`Greutatea corpului stă mai ales pe piciorul din față.`]},"reverse-lunge":{name:`Fandări înapoi`,description:`Fandare cu pas înapoi. Antrenează cvadricepșii și fesierii, dezvoltă echilibrul și coordonarea.`,steps:[`Stai drept, cu tălpile la lățimea șoldurilor.`,`Fă un pas înapoi și coboară, îndoind ambii genunchi.`,`Împinge cu piciorul din față și revino în poziția de start.`,`Alternează picioarele sau fă toate repetările pe aceeași parte.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Fă pasul înapoi controlat, fără smucituri.`,`Ține trunchiul drept.`]},"glute-bridge":{name:`Pod pentru fese`,description:`Ridicarea bazinului din poziția culcat pe spate. Antrenează fesierii și partea posterioară a coapsei.`,steps:[`Culcă-te pe spate, îndoaie genunchii, tălpile pe podea.`,`Contractă fesierii și ridică bazinul în sus.`,`Menține o secundă în punctul de sus.`,`Coboară încet bazinul pe podea.`],warnings:[`Oprește exercițiul dacă simți durere în zona lombară.`],techniqueNotes:[`Nu arcui zona lombară în punctul de sus.`,`Apasă în podea cu călcâiele.`]},"single-leg-glute-bridge":{name:`Pod pentru fese pe un picior`,description:`Variantă mai grea a podului pentru fese, cu sprijin pe un singur picior. Antrenează fesierii și partea posterioară a coapsei și îmbunătățește stabilitatea bazinului.`,steps:[`Culcă-te pe spate, îndoaie genunchii, tălpile pe podea.`,`Întinde un picior și ridică-l deasupra podelei.`,`Ridică bazinul, împingând în călcâiul piciorului de sprijin.`,`Coboară încet; după serie, schimbă piciorul.`],warnings:[`Oprește exercițiul dacă simți durere în zona lombară.`],techniqueNotes:[`Ține bazinul drept, fără să-l înclini.`,`Mișcă-te lent și controlat.`]},"knee-push-up":{name:`Flotări pe genunchi`,description:`Variantă ușurată a flotărilor, cu sprijin pe genunchi. Antrenează pectoralii și tricepșii.`,steps:[`Stai în genunchi, cu palmele pe podea, puțin mai late decât umerii.`,`Aliniază corpul de la genunchi până la cap.`,`Îndoaie brațele și coboară pieptul spre podea.`,`Împinge și întinde brațele.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi sau umeri.`],techniqueNotes:[`Coatele în unghi de aproximativ 45° față de trunchi.`,`Nu lăsa zona lombară să cedeze.`]},"push-up":{name:`Flotări`,description:`Flotările clasice de la podea. Antrenează pectoralii, tricepșii și stabilizatorii trunchiului.`,steps:[`Adoptă poziția de sprijin culcat, cu palmele puțin mai late decât umerii.`,`Aliniază corpul de la călcâie până la cap.`,`Îndoaie brațele și coboară pieptul spre podea.`,`Împinge și întinde brațele.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi sau umeri.`],techniqueNotes:[`Ține abdomenul și fesierii contractați.`,`Coatele în unghi de aproximativ 45° față de trunchi.`]},"wall-push-up":{name:`Flotări la perete`,description:`Cea mai ușoară variantă de flotări, cu sprijin pe perete. Antrenează pectoralii și tricepșii cu încărcare minimă.`,steps:[`Stai cu fața la perete, la distanța brațelor întinse.`,`Sprijină palmele pe perete, la nivelul umerilor.`,`Îndoaie brațele și apropie pieptul de perete.`,`Împinge și revino în poziția de start.`],warnings:[`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Ține corpul drept, ca o scândură.`,`Cu cât tălpile sunt mai departe de perete, cu atât e mai greu.`]},"pike-push-up":{name:`Flotări în poziția „pike”`,description:`Flotări cu bazinul ridicat, care mută încărcarea pe umeri. Antrenează deltoizii și tricepșii.`,steps:[`Adoptă poziția de sprijin culcat și ridică bazinul, formând un „V” inversat.`,`Îndoaie brațele și coboară capul spre podea, între palme.`,`Împinge și întinde brațele.`,`Ține bazinul sus pe tot parcursul seriei.`],warnings:[`Coboară încet și nu te sprijini cu capul pe podea.`,`Oprește exercițiul dacă apare durere la umeri, încheieturi sau gât.`],techniqueNotes:[`Coatele sunt îndreptate înapoi, nu în lateral.`,`Privirea spre podea, între palme.`]},plank:a,"side-plank":{name:`Plank lateral`,description:`Menținerea statică a corpului pe o parte, cu sprijin pe antebraț. Antrenează oblicii și stabilizatorii trunchiului.`,steps:[`Întinde-te pe o parte, cu cotul sub umăr.`,`Pune tălpile una peste alta sau una în fața celeilalte.`,`Ridică bazinul, aliniind corpul.`,`Menține poziția timpul stabilit, apoi schimbă partea.`],warnings:[`Oprește exercițiul dacă apare durere la umăr.`],techniqueNotes:[`Nu lăsa bazinul să cadă.`,`Ține gâtul în linie cu corpul.`]},"dead-bug":{name:`Dead bug`,description:`Întinderea alternativă a brațului și a piciorului opus, culcat pe spate. Antrenează mușchii profunzi ai trunchiului și controlul zonei lombare.`,steps:[`Culcă-te pe spate, cu brațele întinse în sus și picioarele îndoite la unghi drept.`,`Coboară încet brațul și piciorul opus spre podea.`,`Revino în poziția de start.`,`Repetă cu cealaltă pereche braț-picior.`],warnings:[],techniqueNotes:[`Apasă zona lombară pe podea.`,`Mișcă-te lent și expiră în timpul coborârii.`]},"bird-dog":{name:`Bird dog`,description:`Întinderea alternativă a brațului și a piciorului opus în sprijin pe genunchi. Antrenează mușchii trunchiului, fesierii și coordonarea.`,steps:[`Stai în patru labe, cu palmele sub umeri și genunchii sub șolduri.`,`Întinde simultan un braț înainte și piciorul opus înapoi.`,`Menține o secundă.`,`Revino în poziția de start și schimbă partea.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi.`],techniqueNotes:[`Ține spatele drept, nu-l arcui.`,`Bazinul rămâne paralel cu podeaua.`]},superman:r,"wall-sit":{name:`Scaun la perete`,description:`Menținerea statică a poziției șezând cu spatele la perete. Antrenează cvadricepșii și rezistența picioarelor.`,steps:[`Stai cu spatele la perete, cu tălpile la aproximativ o jumătate de metru de el.`,`Alunecă cu spatele în jos până când genunchii formează un unghi confortabil.`,`Menține poziția timpul stabilit.`,`Urcă încet.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Genunchii deasupra gleznelor, fără să depășească vârfurile.`,`Spatele complet lipit de perete.`]},"jumping-jacks":{name:`Jumping jacks`,description:`Sărituri cu depărtarea simultană a brațelor și picioarelor. Dezvoltă rezistența cardiovasculară și încălzesc tot corpul.`,steps:[`Stai drept, cu picioarele lipite și brațele pe lângă corp.`,`Sari și depărtează picioarele, ridicând brațele deasupra capului.`,`Sari și revino în poziția de start.`,`Continuă într-un ritm uniform timpul stabilit.`],warnings:[`Aterizează moale pe partea din față a tălpii.`,`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Genunchii ușor îndoiți la aterizare.`,`Respiră uniform.`]},"step-jacks":{name:`Jumping jacks cu pași`,description:`Variantă fără impact a jumping jacks: pas lateral cu ridicarea brațelor deasupra capului. Încălzește corpul și crește pulsul fără sărituri.`,steps:[`Stai drept, cu picioarele lipite și brațele pe lângă corp.`,`Fă un pas în lateral și ridică simultan brațele deasupra capului.`,`Adu piciorul lângă celălalt și coboară brațele.`,`Alternează părțile într-un ritm uniform.`],warnings:[],techniqueNotes:[`Menține un ritm la care pulsul crește moderat.`,`Calcă moale.`]},"high-knees":{name:`Alergare cu genunchii sus`,description:`Alergare pe loc cu genunchii ridicați sus. Dezvoltă rezistența cardiovasculară și viteza picioarelor.`,steps:[`Stai drept, cu tălpile la lățimea șoldurilor.`,`Începe să alergi pe loc, ridicând genunchii aproximativ până la nivelul șoldurilor.`,`Mișcă brațele în ritmul picioarelor.`,`Continuă timpul stabilit.`],warnings:[`Aterizează moale pe partea din față a tălpii.`,`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Ține trunchiul vertical.`,`Nu te înclina pe spate.`]},"march-in-place":{name:`Marș pe loc`,description:`Mers pe loc cu mișcarea activă a brațelor. Exercițiu cardio ușor, fără impact, pentru încălzire și creșterea pulsului.`,steps:[`Stai drept, cu brațele îndoite la coate.`,`Ridică alternativ genunchii, mărșăluind pe loc.`,`Mișcă brațele în ritmul pașilor.`,`Menține un ritm uniform timpul stabilit.`],warnings:[],techniqueNotes:[`Ține spatele drept.`,`Pentru a-l face mai greu, ridică genunchii mai sus sau accelerează ritmul.`]},"mountain-climbers":{name:`Mountain climbers`,description:`Aducerea alternativă a genunchilor la piept din sprijin culcat. Dezvoltă rezistența și antrenează mușchii trunchiului.`,steps:[`Adoptă poziția de sprijin culcat, cu palmele sub umeri.`,`Adu un genunchi la piept.`,`Întinde piciorul înapoi și adu celălalt genunchi la piept.`,`Alternează picioarele într-un ritm rapid, dar controlat.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi sau umeri.`],techniqueNotes:[`Nu ridica bazinul prea sus.`,`Ține umerii deasupra palmelor.`]},burpee:n,"squat-jump":{name:`Genuflexiuni cu săritură`,description:`Genuflexiune cu săritură explozivă în sus. Dezvoltă forța picioarelor și explozivitatea.`,steps:[`Stai cu tălpile la lățimea umerilor.`,`Fă o genuflexiune până la o adâncime confortabilă.`,`Sari exploziv în sus.`,`Aterizează moale și intră imediat în genuflexiune.`],warnings:[`Aterizează moale, cu picioarele îndoite.`,`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Genunchii merg în direcția degetelor de la picioare.`,`Aterizarea e silențioasă și controlată.`]},"cat-cow":{name:`Pisică-vacă`,description:`Rotunjirea și arcuirea lină, alternativă, a spatelui în sprijin pe genunchi. Îmbunătățește mobilitatea coloanei.`,steps:[`Stai în patru labe, cu palmele sub umeri.`,`Inspirând, arcuiește spatele și ridică privirea.`,`Expirând, rotunjește spatele și coboară capul.`,`Repetă lin, în ritmul respirației.`],warnings:[`Mișcă-te într-o amplitudine confortabilă și oprește-te dacă apare durere.`],techniqueNotes:[`Mișcarea pornește de la bazin spre cap.`,`Nu te grăbi.`]},"kneeling-hip-flexor-stretch":{name:`Întindere pentru flexorii șoldului în genunchi`,description:`Întinderea feței anterioare a coapsei în poziție de fandare pe un genunchi. Îmbunătățește mobilitatea șoldului.`,steps:[`Pune un genunchi pe podea, cu celălalt picior în față, îndoit la unghi drept.`,`Contractă fesierul piciorului aflat în genunchi.`,`Împinge lin bazinul înainte până simți întinderea.`,`Menține poziția timpul stabilit și schimbă piciorul.`],warnings:[`Pune ceva moale sub genunchi; oprește-te dacă apare durere.`],techniqueNotes:[`Nu arcui zona lombară.`,`Întinderea trebuie să fie moderată, fără durere.`]},"arm-circles":{name:`Cercuri cu brațele`,description:`Rotiri circulare cu brațele întinse. Încălzesc articulațiile umerilor și le îmbunătățesc mobilitatea.`,steps:[`Stai drept și depărtează brațele în lateral.`,`Fă cercuri mici cu brațele înainte.`,`Mărește treptat amplitudinea.`,`După jumătate din timp, schimbă direcția.`],warnings:[`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Umerii jos, nu-i trage spre urechi.`,`Mișcă-te lin.`]},"open-book-rotation":{name:`Rotație „carte deschisă”`,description:`Rotirea porțiunii toracice a coloanei, culcat pe o parte. Îmbunătățește mobilitatea toracelui și a umerilor.`,steps:[`Culcă-te pe o parte, cu genunchii îndoiți și brațele întinse în față.`,`Mută brațul de sus într-un arc spre partea opusă, rotind pieptul.`,`Urmărește mâna cu privirea.`,`Adu brațul înapoi; după serie, schimbă partea.`],warnings:[`Mișcă-te într-o amplitudine confortabilă și oprește-te dacă apare durere.`],techniqueNotes:[`Genunchii rămân împreună pe podea.`,`Respiră calm.`]},"goblet-squat":{name:`Genuflexiuni goblet`,description:`Genuflexiune cu o ganteră sau un kettlebell lângă piept. Antrenează cvadricepșii și fesierii și ajută la menținerea trunchiului vertical.`,steps:[`Ține ganterele sau kettlebellul vertical, lângă piept.`,`Stai cu tălpile puțin mai late decât umerii.`,`Fă genuflexiunea, ținând pieptul ridicat.`,`Urcă, împingând în tălpi.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi sau în spate.`],techniqueNotes:[`Coatele merg între genunchi.`,`Spatele drept pe toată durata mișcării.`]},"dumbbell-romanian-deadlift":{name:`Îndreptări românești cu gantere`,description:`Aplecare înainte cu gantere, prin mișcarea articulațiilor șoldului. Antrenează partea posterioară a coapsei și fesierii.`,steps:[`Stai drept, cu ganterele în fața coapselor.`,`Îndoaie ușor genunchii și împinge șoldurile înapoi.`,`Coboară ganterele de-a lungul picioarelor până simți întinderea în partea posterioară a coapsei.`,`Revino în sus, împingând șoldurile înainte.`],warnings:[`Nu rotunji spatele; alege o greutate cu care îți menții tehnica.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Spatele drept, ganterele aproape de picioare.`,`Mișcarea pornește de la șolduri, nu de la spate.`]},"one-arm-dumbbell-row":{name:`Ramat cu ganteră cu o mână`,description:`Tragerea gantelei spre talie în aplecare, cu sprijin pe mână. Antrenează mușchii spatelui și bicepșii.`,steps:[`Apleacă-te înainte, sprijinind mâna liberă pe coapsă sau pe un suport stabil.`,`Ia ganterele cu brațul întins sub umăr.`,`Trage ganterele spre talie, ducând cotul înapoi.`,`Coboară încet; după serie, schimbă brațul.`],warnings:[`Ține spatele drept; oprește-te dacă apare durere în zona lombară.`],techniqueNotes:[`Nu roti trunchiul în timpul tragerii.`,`Apropie omoplatul de coloană.`]},"dumbbell-floor-press":{name:`Presă cu gantere pe podea`,description:`Presă cu gantere în sus, culcat pe podea, cu amplitudine limitată. Antrenează pectoralii și tricepșii.`,steps:[`Culcă-te pe spate, cu genunchii îndoiți și ganterele în mâini, lângă piept.`,`Împinge ganterele în sus, deasupra pieptului.`,`Coboară încet până când umerii ating podeaua.`,`Repetă presa.`],warnings:[`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Coatele în unghi de aproximativ 45° față de trunchi.`,`Coboară ganterele controlat, fără să lovești podeaua.`]},"dumbbell-bench-press":{name:`Presă cu gantere pe bancă`,description:`Presă cu gantere în sus, culcat pe o bancă orizontală. Antrenează pectoralii și tricepșii.`,steps:[`Întinde-te pe bancă, cu tălpile pe podea și ganterele lângă piept.`,`Împinge ganterele în sus, deasupra pieptului.`,`Coboară-le încet până la nivelul pieptului.`,`Repetă presa.`],warnings:[`Alege o greutate pe care o poți coborî controlat.`,`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Omoplații uniți și lipiți de bancă.`,`Nu arunca ganterele de pe piept.`]},"incline-dumbbell-press":{name:`Presă cu gantere pe bancă înclinată`,description:`Presă cu gantere, culcat pe o bancă cu spătarul ridicat. Antrenează partea superioară a pectoralilor și deltoizii anteriori.`,steps:[`Reglează spătarul băncii la un unghi moderat de înclinare.`,`Așază-te pe bancă, cu spatele lipit și ganterele lângă piept.`,`Împinge ganterele în sus, deasupra părții superioare a pieptului.`,`Coboară încet și repetă.`],warnings:[`Asigură-te că spătarul băncii este bine fixat.`,`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Omoplații uniți și lipiți de bancă.`,`Mișcă-te controlat pe toată amplitudinea.`]},"dumbbell-shoulder-press":{name:`Presă cu gantere deasupra capului`,description:`Presă cu gantere în sus, în picioare. Antrenează deltoizii și tricepșii.`,steps:[`Stai drept, cu ganterele la nivelul umerilor.`,`Contractă abdomenul și fesierii.`,`Împinge ganterele în sus, deasupra capului.`,`Coboară încet până la nivelul umerilor.`],warnings:[`Nu arcui zona lombară în timpul presei.`,`Oprește exercițiul dacă apare durere la umeri, gât sau în spate.`],techniqueNotes:[`Coastele jos, trunchiul stabil.`,`Nu da capul pe spate.`]},"dumbbell-reverse-lunge":{name:`Fandări înapoi cu gantere`,description:`Fandare cu pas înapoi, cu gantere în mâini. Antrenează cvadricepșii și fesierii cu încărcare suplimentară.`,steps:[`Stai drept, cu ganterele în brațele lăsate pe lângă corp.`,`Fă un pas înapoi și coboară, îndoind ambii genunchi.`,`Împinge cu piciorul din față și revino în poziția de start.`,`Alternează picioarele sau fă toate repetările pe aceeași parte.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Ține trunchiul vertical.`,`Umerii jos, ganterele nu se leagănă.`]},"farmer-carry":{name:`Plimbarea fermierului`,description:`Mers cu gantere sau kettlebelluri în brațele lăsate pe lângă corp. Antrenează trunchiul, priza și stabilitatea generală.`,steps:[`Ia ganterele sau kettlebellurile în ambele mâini.`,`Îndreaptă-te, cu umerii jos și trași înapoi.`,`Mergi cu pași scurți și uniformi timpul stabilit.`,`Pune cu grijă greutatea pe podea.`],warnings:[`Ridică și pune greutatea cu spatele drept.`,`Oprește exercițiul dacă apare durere în spate sau la încheieturi.`],techniqueNotes:[`Nu te înclina spre partea greutății.`,`Ține abdomenul contractat.`]},"kettlebell-swing":{name:`Swing cu kettlebell`,description:`Balansul dinamic al kettlebellului prin mișcarea articulațiilor șoldului. Dezvoltă puterea fesierilor și a părții posterioare a coapsei, precum și rezistența.`,steps:[`Stai cu tălpile puțin mai late decât umerii, cu kettlebellul în fața ta.`,`Apleacă-te cu spatele drept și trece kettlebellul înapoi, printre picioare.`,`Împinge brusc șoldurile înainte, astfel încât kettlebellul să urce la nivelul pieptului.`,`Lasă kettlebellul să coboare și repetă mișcarea.`],warnings:[`Asigură-te că nu sunt oameni sau obiecte în jur.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Mișcarea pornește de la șolduri, brațele doar țin kettlebellul.`,`Spatele drept în punctul de jos.`]},"kettlebell-deadlift":{name:`Îndreptări cu kettlebell`,description:`Ridicarea kettlebellului de la podea prin mișcarea articulațiilor șoldului. Antrenează fesierii și partea posterioară a coapsei și învață ridicarea corectă a greutăților.`,steps:[`Stai deasupra kettlebellului, cu tălpile la lățimea șoldurilor.`,`Împinge șoldurile înapoi, îndoaie genunchii și apucă mânerul kettlebellului.`,`Îndreaptă-te, împingând șoldurile înainte.`,`Coboară kettlebellul pe podea cu aceeași mișcare.`],warnings:[`Nu rotunji spatele în timpul ridicării.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Spatele drept, privirea înainte.`,`Kettlebellul se mișcă aproape de corp.`]},"band-pull-apart":{name:`Depărtarea benzii elastice`,description:`Întinderea unei benzi elastice cu brațele drepte, în fața pieptului. Antrenează mușchii părții superioare a spatelui și deltoizii posteriori.`,steps:[`Ține banda cu ambele mâini, la lățimea umerilor, în fața pieptului.`,`Depărtează brațele în lateral, întinzând banda.`,`Apropie omoplații în punctul final.`,`Adu încet brațele înapoi în poziția de start.`],warnings:[`Verifică banda înainte de exercițiu, să nu fie deteriorată.`],techniqueNotes:[`Umerii jos, nu-i ridica spre urechi.`,`Brațele aproape drepte pe toată durata mișcării.`]},"band-row":{name:`Ramat cu bandă elastică spre talie`,description:`Tragerea unei benzi fixate spre talie. Antrenează mușchii spatelui și bicepșii.`,steps:[`Fixează banda la nivelul taliei de un suport stabil.`,`Apucă capetele și dă-te înapoi până când banda se întinde.`,`Trage brațele spre talie, ducând coatele înapoi.`,`Adu încet brațele înainte.`],warnings:[`Verifică dacă fixarea este sigură și banda nu este deteriorată.`],techniqueNotes:[`Apropie omoplații în punctul final.`,`Trunchiul nemișcat, nu te înclina pe spate.`]},"band-lat-pulldown":{name:`Tragere de sus cu bandă elastică`,description:`Tragerea în jos, spre piept, a unei benzi fixate sus. Antrenează mușchii dorsali și bicepșii.`,steps:[`Fixează banda deasupra capului de un suport stabil.`,`Apucă capetele, cu brațele întinse în sus.`,`Trage coatele în jos, spre părțile laterale, apropiind mâinile de piept.`,`Adu încet brațele în sus.`],warnings:[`Verifică dacă fixarea de sus este sigură și banda nu este deteriorată.`,`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Coboară omoplații înainte de tragere.`,`Nu legăna trunchiul.`]},"pull-up":{name:`Tracțiuni`,description:`Ridicarea corpului la bară până la nivelul bărbiei. Antrenează mușchii spatelui și bicepșii.`,steps:[`Apucă bara cu priza puțin mai largă decât umerii.`,`Atârnă cu brațele întinse, cu omoplații coborâți.`,`Trage-te în sus până când bărbia ajunge deasupra barei.`,`Coboară încet, până la brațe întinse.`],warnings:[`Folosește doar o bară montată sigur.`,`Oprește exercițiul dacă apare durere la umeri sau încheieturi.`],techniqueNotes:[`Nu te legăna și nu smuci.`,`Coboară controlat.`]},"dead-hang":{name:`Atârnare la bară`,description:`Atârnare statică la bară, cu brațele întinse. Întărește priza și mușchii centurii scapulare.`,steps:[`Apucă bara cu priza la lățimea umerilor.`,`Atârnă cu grijă, cu brațele întinse.`,`Menține poziția timpul stabilit, respirând uniform.`,`Coboară cu grijă pe podea.`],warnings:[`Folosește doar o bară montată sigur.`,`Oprește exercițiul dacă apare durere la umeri sau încheieturi.`],techniqueNotes:[`Contractă ușor umerii, nu atârna pasiv.`,`Nu te legăna.`]},"hanging-knee-raise":{name:`Ridicări de genunchi din atârnat`,description:`Aducerea genunchilor la piept din atârnat la bară. Antrenează mușchii abdominali și priza.`,steps:[`Atârnă de bară cu brațele întinse.`,`Contractă abdomenul și adu genunchii la piept.`,`Menține o secundă.`,`Coboară încet picioarele, fără să te legeni.`],warnings:[`Folosește doar o bară montată sigur.`,`Oprește exercițiul dacă apare durere la umeri sau în zona lombară.`],techniqueNotes:[`Mișcă-te fără smucituri și balansuri.`,`Rotunjește ușor bazinul în punctul de sus.`]},"jump-rope":{name:`Sărituri cu coarda`,description:`Sărituri ritmice peste coardă. Dezvoltă rezistența cardiovasculară, coordonarea și forța gambelor.`,steps:[`Ia mânerele corzii, cu coarda în spatele călcâielor.`,`Rotește coarda din încheieturi.`,`Fă sărituri mici când coarda trece pe sub tălpi.`,`Menține un ritm uniform timpul stabilit.`],warnings:[`Sari puțin și aterizează moale pe partea din față a tălpii.`,`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Coatele aproape de corp.`,`Genunchii ușor îndoiți.`]},"step-up":{name:`Urcări pe platformă`,description:`Urcarea alternativă pe o platformă stabilă cu fiecare picior. Antrenează cvadricepșii și fesierii.`,steps:[`Stai în fața platformei.`,`Pune pe ea toată talpa unui picior.`,`Urcă, împingând cu piciorul de pe platformă.`,`Coboară încet și repetă; după serie, schimbă piciorul.`],warnings:[`Asigură-te că platforma este stabilă și nu alunecă.`,`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Nu te împinge cu piciorul de jos.`,`Genunchiul merge în direcția degetelor.`]},"barbell-back-squat":{name:`Genuflexiuni cu bara pe spate`,description:`Genuflexiune cu bara pe partea superioară a spatelui. Dezvoltă forța cvadricepșilor, a fesierilor și a întregului corp.`,steps:[`Așază bara pe partea superioară a spatelui și scoate-o din stativ.`,`Fă un pas înapoi, cu tălpile la lățimea umerilor sau puțin mai late.`,`Fă genuflexiunea până la o adâncime confortabilă, cu spatele drept.`,`Urcă, iar după serie pune bara înapoi în stativ.`],warnings:[`Reglează barele de siguranță ale stativului și lucrează cu o greutate pe care o controlezi.`,`Oprește exercițiul dacă apare durere la genunchi, în spate sau la umeri.`],techniqueNotes:[`Contractă trunchiul înainte de fiecare repetare.`,`Genunchii merg în direcția degetelor de la picioare.`]},"barbell-deadlift":{name:`Îndreptări cu bara`,description:`Ridicarea barei de la podea până în poziția în picioare. Dezvoltă forța părții posterioare a coapsei, a fesierilor și a spatelui.`,steps:[`Stai astfel încât bara să fie deasupra mijlocului tălpii.`,`Împinge șoldurile înapoi, îndoaie genunchii și apucă bara.`,`Îndreaptă-te, ținând bara aproape de picioare.`,`Coboară bara pe podea cu aceeași mișcare.`],warnings:[`Nu rotunji spatele; lucrează cu o greutate pe care o controlezi.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Spatele drept, trunchiul contractat.`,`Împinge în podea cu picioarele, nu trage cu spatele.`]},"cardio-machine-intervals":{name:`Intervale la aparatul cardio`,description:`Lucru pe intervale la bicicleta, eliptica sau alt aparat cardio. Dezvoltă rezistența cardiovasculară.`,steps:[`Încălzește-te câteva minute într-un ritm ușor.`,`Crește ritmul sau rezistența pentru durata stabilită a intervalului.`,`În timpul pauzei, continuă să te miști într-un ritm ușor.`,`Repetă intervalul de numărul stabilit de ori.`],warnings:[`Citește instrucțiunile aparatului înainte de folosire.`,`Scade ritmul sau oprește-te dacă apar amețeli sau durere.`],techniqueNotes:[`Intensitatea trebuie să fie simțită, dar controlată.`,`Păstrează o postură dreaptă.`]},"jump-rope-boxer-step":{name:`Pas de boxer cu coarda`,description:`Sărituri joase cu coarda, cu transferul alternativ al greutății de pe un picior pe altul. Mai simplu decât săriturile pe ambele picioare.`,steps:[`Ia mânerele corzii, cu coarda în spatele călcâielor.`,`Rotește coarda din încheieturi.`,`Transferă ușor greutatea de pe un picior pe altul, ca și cum ai merge pe loc.`,`Menține un ritm uniform timpul stabilit.`],warnings:[`Sari puțin și aterizează moale pe partea din față a tălpii.`,`Oprește exercițiul dacă apare durere la glezne.`],techniqueNotes:[`Săritura e de doar câțiva centimetri de la podea.`,`Coatele aproape de corp.`]},"jump-rope-side-to-side":{name:`Sărituri cu coarda dintr-o parte în alta`,description:`Sărituri pe ambele picioare, cu o mică deplasare spre stânga și spre dreapta. Adaugă încărcare pe gambe și antrenează coordonarea.`,steps:[`Ia mânerele corzii, cu picioarele lipite.`,`Sari peste coardă, deplasându-te puțin spre stânga.`,`La săritura următoare, deplasează-te spre dreapta.`,`Menține ritmul și aterizează moale.`],warnings:[`Asigură-te că ai destul loc și că suprafața nu alunecă.`,`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Deplasarea e mică, nu mai lată decât tălpile.`,`Genunchii ușor îndoiți.`]},"jump-rope-high-knees":{name:`Alergare cu coarda`,description:`Alergare pe loc peste coardă, cu ridicarea genunchilor. Exercițiu cardio intens pentru rezistență.`,steps:[`Ia mânerele corzii, cu coarda în spatele călcâielor.`,`Aleargă pe loc, trecând coarda pe sub talpă la fiecare pas.`,`Ridică genunchii până la nivelul șoldurilor.`,`Menține ritmul timpul stabilit.`],warnings:[`Fă exercițiul doar după încălzire.`,`Oprește exercițiul dacă apare durere la genunchi, șolduri sau glezne.`],techniqueNotes:[`Trunchiul drept, nu te înclina pe spate.`,`Aterizarea moale, pe partea din față a tălpii.`]},"lateral-step-up":{name:`Urcare laterală pe step`,description:`Urcarea pe platformă cu partea laterală spre ea. Solicită fesierii și mușchii coapsei sub alt unghi decât urcarea obișnuită.`,steps:[`Stai cu o parte spre platformă, cu piciorul apropiat pus pe ea.`,`Întinde piciorul, urcând pe platformă.`,`Coboară controlat înapoi.`,`Termină seriile pe un picior, apoi schimbă piciorul.`],warnings:[`Asigură-te că platforma este stabilă și nu alunecă.`,`Oprește exercițiul dacă apare durere la genunchi sau șolduri.`],techniqueNotes:[`Lucrează piciorul de sprijin, celălalt doar atinge.`,`Genunchiul nu cade spre interior.`]},"step-platform-push-up":{name:`Flotări cu mâinile pe step`,description:`Flotări cu mâinile pe platformă. Variantă mai ușoară a flotărilor clasice, pentru începători.`,steps:[`Pune mâinile pe platformă, puțin mai late decât umerii, cu corpul într-o linie dreaptă.`,`Îndoaie coatele, coborând pieptul spre platformă.`,`Împinge, întinzând brațele.`,`Ține trunchiul contractat.`],warnings:[`Platforma trebuie să stea stabil, de preferat pe o suprafață antiderapantă.`,`Oprește exercițiul dacă apare durere la încheieturi sau umeri.`],techniqueNotes:[`Nu arcui zona lombară.`,`Coatele în unghi de aproximativ 45° față de trunchi.`]},"step-platform-calf-raise":{name:`Ridicări pe vârfuri pe step`,description:`Ridicări pe vârfuri de pe marginea platformei, pentru o amplitudine mai mare. Întăresc mușchii gambei.`,steps:[`Stai pe marginea platformei, cu partea din față a tălpilor, iar călcâiele în aer.`,`Coboară încet călcâiele sub nivelul platformei.`,`Ridică-te cât mai sus pe vârfuri.`,`Repetă fără smucituri.`],warnings:[`Ține-te de perete sau de un suport pentru echilibru.`,`Oprește exercițiul dacă apare durere la glezne sau la tendonul lui Ahile.`],techniqueNotes:[`Mișcarea e lentă: 2 secunde în sus, 2 în jos.`,`Genunchii aproape drepți.`]},"step-platform-reverse-lunge":{name:`Fandare înapoi de pe step`,description:`Pas înapoi de pe platformă într-o fandare. Amplitudine mărită pentru fesieri și coapse.`,steps:[`Stai pe platformă, cu picioarele la lățimea șoldurilor.`,`Fă un pas înapoi cu un picior, pe podea.`,`Coboară în fandare, cu piciorul din față rămas pe platformă.`,`Revino în poziția de start și schimbă piciorul.`],warnings:[`Asigură-te că platforma este stabilă și nu alunecă.`,`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Trunchiul vertical.`,`Călcâiul din față apăsat pe platformă.`]},"step-platform-taps":{name:`Atingeri ale stepului`,description:`Atingeri rapide, alternative, ale platformei cu tălpile. Exercițiu cardio ușor pentru încălzire și rezistență.`,steps:[`Stai în fața platformei.`,`Atinge platforma cu piciorul drept, apoi cu cel stâng.`,`Mișcă-te rapid și ușor, fără să calci cu toată talpa.`,`Menține ritmul timpul stabilit.`],warnings:[`Platforma trebuie să stea stabil.`,`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Spatele drept, brațele lucrează în ritm.`,`Mișcările sunt ușoare, fără lovituri.`]},"bench-dip":{name:`Flotări pe bancă (dips)`,description:`Flotări pentru triceps, cu mâinile sprijinite pe o bancă în spatele tău.`,steps:[`Așază-te pe marginea băncii, cu mâinile lângă coapse.`,`Alunecă înainte, ținându-te cu mâinile de bancă.`,`Îndoaie coatele la aproximativ 90°.`,`Întinde brațele și revino în sus.`],warnings:[`Nu coborî adânc dacă simți disconfort la umeri.`,`Banca trebuie să stea stabil.`,`Oprește exercițiul dacă apare durere la umeri sau încheieturi.`],techniqueNotes:[`Coatele sunt îndreptate înapoi, nu în lateral.`,`Nu ridica umerii spre urechi.`]},"bulgarian-split-squat":{name:`Genuflexiuni bulgărești`,description:`Genuflexiune pe un picior, cu piciorul din spate pe o bancă. Solicită puternic fesierii și coapsele.`,steps:[`Stai cu spatele la bancă și pune vârful unui picior pe bancă.`,`Coboară, îndoind piciorul din față.`,`Urcă, împingând în călcâiul piciorului din față.`,`Fă toate repetările, apoi schimbă piciorul.`],warnings:[`Banca trebuie să fie stabilă; alege distanța astfel încât genunchiul să nu depășească laba piciorului.`,`Oprește exercițiul dacă apare durere la genunchi sau șolduri.`],techniqueNotes:[`Trunchiul ușor înclinat înainte.`,`Greutatea principală pe piciorul din față.`]},"bench-hip-thrust":{name:`Hip thrust pe bancă`,description:`Ridicarea bazinului cu omoplații sprijiniți pe bancă. Exercițiul principal pentru fese.`,steps:[`Stai pe podea cu spatele la bancă, cu omoplații pe marginea ei.`,`Îndoaie genunchii, cu tălpile pe podea.`,`Ridică bazinul până când trunchiul și coapsele formează o linie.`,`Menține o clipă și coboară.`],warnings:[`Banca trebuie să fie nemișcată, de preferat lângă perete.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Bărbia ușor lipită de piept.`,`Nu arcui zona lombară în punctul de sus.`]},"chest-supported-dumbbell-row":{name:`Ramat cu gantere cu sprijin pe bancă`,description:`Tragerea ganterelor, cu pieptul sprijinit pe o bancă înclinată. Descarcă zona lombară și concentrează efortul pe spate.`,steps:[`Întinde-te cu pieptul pe bancă, cu câte o ganteră în fiecare mână.`,`Trage ganterele spre părțile laterale ale trunchiului, apropiind omoplații.`,`Menține o clipă.`,`Coboară controlat ganterele.`],warnings:[`Banca trebuie să stea stabil.`,`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Capul continuă linia coloanei.`,`Nu legăna trunchiul.`]},"kettlebell-single-arm-row":{name:`Ramat cu kettlebell cu o mână`,description:`Tragerea kettlebellului în aplecare, cu sprijinul mâinii libere. Întărește spatele și bicepsul.`,steps:[`Apleacă-te înainte cu spatele drept, sprijinind mâna liberă pe coapsă.`,`Ia kettlebellul cu cealaltă mână.`,`Trage kettlebellul spre talie, apropiind omoplatul.`,`Coboară kettlebellul încet.`],warnings:[`Ține spatele drept.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Cotul se mișcă de-a lungul trunchiului.`,`Privirea spre podea.`]},"kettlebell-overhead-press":{name:`Presă cu kettlebell deasupra capului`,description:`Presă cu kettlebellul în picioare, cu o mână. Întărește umerii, tricepsul și trunchiul.`,steps:[`Ridică kettlebellul la umăr, cu cotul lipit de trunchi.`,`Contractă abdomenul și fesierii.`,`Întinde brațul în sus, deasupra capului.`,`Adu încet kettlebellul înapoi la umăr.`],warnings:[`Asigură-te că ai destul loc deasupra ta.`,`Oprește exercițiul dacă apare durere la umeri, gât sau în zona lombară.`],techniqueNotes:[`Nu arcui zona lombară.`,`Încheietura dreaptă, kettlebellul se sprijină pe antebraț.`]},"kettlebell-halo":{name:`Halo cu kettlebell`,description:`Mișcări circulare ale kettlebellului în jurul capului. Încălzește umerii și lucrează stabilitatea trunchiului.`,steps:[`Stai drept, ținând kettlebellul cu fundul în sus, lângă piept.`,`Trece kettlebellul în jurul capului într-o direcție.`,`Adu-l înapoi la piept.`,`Repetă în cealaltă direcție.`],warnings:[`Folosește un kettlebell ușor.`,`Ține kettlebellul ferm, ca să nu te lovești.`,`Oprește exercițiul dacă apare durere la umeri sau gât.`],techniqueNotes:[`Trunchiul nemișcat, lucrează doar brațele.`,`Coatele aproape de cap.`]},"kettlebell-sumo-deadlift":{name:`Îndreptări sumo cu kettlebell`,description:`Ridicarea kettlebellului cu picioarele depărtate. Solicită fesierii și fața interioară a coapselor.`,steps:[`Stai larg, cu vârfurile depărtate și kettlebellul între tălpi.`,`Împinge șoldurile înapoi și apucă kettlebellul.`,`Îndreaptă-te, împingând în podea cu picioarele.`,`Coboară încet kettlebellul.`],warnings:[`Nu rotunji spatele.`,`Oprește exercițiul dacă apare durere în zona lombară sau la șolduri.`],techniqueNotes:[`Genunchii merg în direcția degetelor de la picioare.`,`Spatele drept pe toată durata mișcării.`]},"kettlebell-reverse-lunge":{name:`Fandare înapoi cu kettlebell`,description:`Fandare cu pas înapoi, cu kettlebellul lângă piept. Adaugă încărcare pe picioare și fesieri.`,steps:[`Ține kettlebellul lângă piept, cu ambele mâini.`,`Fă un pas înapoi și coboară în fandare.`,`Împinge cu piciorul din față și revino.`,`Schimbă piciorul.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Trunchiul vertical.`,`Călcâiul din față apăsat pe podea.`]},"band-squat":{name:`Genuflexiuni cu bandă elastică`,description:`Genuflexiune cu banda sub tălpi. Banda adaugă rezistență la urcare.`,steps:[`Stai pe mijlocul benzii, ținând capetele la nivelul umerilor.`,`Fă genuflexiunea, împingând șoldurile înapoi.`,`Urcă, întinzând picioarele.`,`Nu da drumul benzii brusc.`],warnings:[`Verifică dacă banda nu este deteriorată.`,`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Genunchii în direcția degetelor.`,`Spatele drept.`]},"band-chest-press":{name:`Presă pentru piept cu bandă elastică`,description:`Împingerea benzii în față, în picioare. Antrenează pieptul și tricepsul fără gantere.`,steps:[`Trece banda pe la spate, sub omoplați, cu capetele în mâini.`,`Îndoaie coatele, cu mâinile la nivelul pieptului.`,`Întinde brațele înainte.`,`Revino încet.`],warnings:[`Verifică dacă banda nu este deteriorată și stă sigur la spate.`,`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Coatele puțin sub nivelul umerilor.`,`Trunchiul nemișcat.`]},"band-overhead-press":{name:`Presă deasupra capului cu bandă elastică`,description:`Împingerea benzii în sus, stând pe ea. Întărește umerii și tricepsul.`,steps:[`Stai pe bandă, ținând capetele la nivelul umerilor.`,`Întinde brațele în sus, deasupra capului.`,`Coboară-le încet până la umeri.`,`Nu arcui zona lombară.`],warnings:[`Asigură-te că ai destul loc deasupra ta.`,`Oprește exercițiul dacă apare durere la umeri sau gât.`],techniqueNotes:[`Abdomenul contractat.`,`Brațele se mișcă vertical.`]},"band-good-morning":{name:`Good morning cu bandă elastică`,description:`Aplecări ale trunchiului cu spatele drept, cu banda pe umeri și sub tălpi. Învață mișcarea de balama.`,steps:[`Stai pe bandă, iar celălalt capăt pune-l pe umeri.`,`Împinge șoldurile înapoi, înclinând trunchiul cu spatele drept.`,`Coboară până simți întinderea în partea posterioară a coapselor.`,`Îndreaptă-te, împingând șoldurile înainte.`],warnings:[`Nu rotunji spatele.`,`Verifică dacă banda este fixată sigur.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Genunchii ușor îndoiți.`,`Privirea în jos și înainte.`]},"band-bicep-curl":{name:`Flexii pentru biceps cu bandă elastică`,description:`Flexia brațelor pentru biceps, cu rezistența benzii.`,steps:[`Stai pe bandă, cu capetele în mâini și palmele înainte.`,`Îndoaie coatele, ridicând mâinile spre umeri.`,`Menține o clipă.`,`Coboară încet brațele.`],warnings:[`Verifică dacă banda nu este deteriorată.`],techniqueNotes:[`Coatele lipite de corp.`,`Trunchiul nu se leagănă.`]},"scapular-pull-up":{name:`Tracțiuni scapulare`,description:`Ridicarea și coborârea omoplaților în atârnat, fără îndoirea brațelor. Pregătește umerii pentru tracțiuni.`,steps:[`Atârnă de bară, cu brațele drepte.`,`Coboară umerii și apropie omoplații, ridicând corpul câțiva centimetri.`,`Revino încet în atârnat.`,`Nu îndoi coatele.`],warnings:[`Folosește doar o bară montată sigur.`,`Oprește exercițiul dacă apare durere la umeri sau încheieturi.`],techniqueNotes:[`Mișcarea e mică, doar din omoplați.`,`Corpul nu se leagănă.`]},"negative-pull-up":{name:`Tracțiuni negative`,description:`Coborârea lentă din poziția de sus a tracțiunii. Ajută la învățarea tracțiunilor.`,steps:[`Urcă pe un scaun și apucă bara, cu bărbia deasupra ei.`,`Îndepărtează sprijinul.`,`Coboară încet până când brațele se întind (3–5 secunde).`,`Revino pe scaun și repetă.`],warnings:[`Folosește doar o bară montată sigur.`,`Folosește un scaun pentru a ajunge în poziția de sus.`,`Oprește exercițiul dacă apare durere la umeri sau încheieturi.`],techniqueNotes:[`Coboară controlat, fără să cazi.`,`Omoplații rămân coborâți.`]},"chin-up":{name:`Tracțiuni cu priză supinată`,description:`Tracțiuni cu palmele spre tine. Solicită bicepsul mai puternic decât tracțiunile obișnuite.`,steps:[`Apucă bara cu priza supinată, la lățimea umerilor.`,`Trage-te în sus până când bărbia ajunge deasupra barei.`,`Menține o clipă.`,`Coboară încet în atârnat.`],warnings:[`Folosește doar o bară montată sigur.`,`Oprește exercițiul dacă apare durere la umeri, coate sau încheieturi.`],techniqueNotes:[`Nu te legăna.`,`Coatele merg în jos și spre trunchi.`]},"hanging-leg-raise":{name:`Ridicări de picioare drepte din atârnat`,description:`Ridicarea picioarelor drepte din atârnat la bară. Variantă mai grea pentru mușchii abdominali.`,steps:[`Atârnă de bară.`,`Contractă abdomenul și ridică picioarele drepte până la nivelul bazinului.`,`Menține o clipă.`,`Coboară încet picioarele.`],warnings:[`Folosește doar o bară montată sigur.`,`Nu te legăna, ridică picioarele încet.`,`Oprește exercițiul dacă apare durere la umeri sau în zona lombară.`],techniqueNotes:[`Bazinul ușor basculat.`,`Fără legănarea corpului.`]},"dumbbell-lateral-raise":{name:`Ridicări laterale cu gantere`,description:`Ridicarea ganterelor în lateral până la nivelul umerilor. Dezvoltă porțiunea mijlocie a deltoizilor.`,steps:[`Stai drept, cu ganterele pe lângă corp.`,`Îndoaie ușor coatele și ridică brațele în lateral până la nivelul umerilor.`,`Coboară încet brațele.`,`Nu ridica umerii spre urechi.`],warnings:[`Alege gantere ușoare.`,`Oprește exercițiul dacă apare durere la umeri sau gât.`],techniqueNotes:[`Coatele puțin mai sus decât mâinile.`,`Trunchiul nemișcat.`]},"dumbbell-bicep-curl":{name:`Flexii pentru biceps cu gantere`,description:`Flexia clasică a brațelor pentru biceps, în picioare.`,steps:[`Stai drept, cu ganterele în brațele coborâte și palmele înainte.`,`Îndoaie coatele, ridicând ganterele spre umeri.`,`Menține o clipă.`,`Coboară încet ganterele.`],warnings:[`Alege o greutate cu care nu ești nevoit să legeni trunchiul.`],techniqueNotes:[`Coatele lipite de corp.`,`Nu te înclina pe spate.`]},"dumbbell-overhead-triceps-extension":{name:`Extensii pentru triceps cu ganteră deasupra capului`,description:`Extensia brațelor cu o ganteră în spatele capului. Izolează tricepsul.`,steps:[`Stai drept, ținând ganterele cu ambele mâini deasupra capului.`,`Îndoaie coatele, coborând ganterele în spatele capului.`,`Întinde brațele în sus.`,`Ține coatele aproape de cap.`],warnings:[`Ține ganterele cu ambele mâini.`,`Oprește exercițiul dacă apare durere la umeri, coate sau gât.`],techniqueNotes:[`Coatele nu se depărtează în lateral.`,`Abdomenul contractat.`]},"dumbbell-sumo-squat":{name:`Genuflexiuni sumo cu ganteră`,description:`Genuflexiune cu picioarele depărtate și o ganteră între picioare. Accent pe fesieri și fața interioară a coapselor.`,steps:[`Stai larg, cu vârfurile depărtate, ținând ganterele cu ambele mâini, jos.`,`Fă genuflexiunea, cu genunchii în direcția degetelor.`,`Urcă, împingând în podea cu picioarele.`,`Ține trunchiul vertical.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi sau șolduri.`],techniqueNotes:[`Spatele drept.`,`Genunchii nu cad spre interior.`]},"dumbbell-glute-bridge":{name:`Pod pentru fese cu ganteră`,description:`Pod pentru fese cu o ganteră pe bazin. Adaugă încărcare pe fesieri.`,steps:[`Culcă-te pe spate, cu genunchii îndoiți și ganterele pe bazin.`,`Ridică bazinul, aliniind corpul.`,`Menține o clipă.`,`Coboară încet.`],warnings:[`Ține ganterele ferm.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Nu arcui zona lombară.`,`Călcâiele apăsate pe podea.`]},"dumbbell-bent-over-row":{name:`Ramat cu gantere în aplecare`,description:`Tragerea a două gantere spre talie, în aplecare. Întărește spatele și bicepsul.`,steps:[`Apleacă-te înainte cu spatele drept, cu ganterele în brațele coborâte.`,`Trage ganterele spre părțile laterale, apropiind omoplații.`,`Menține o clipă.`,`Coboară încet ganterele.`],warnings:[`Ține spatele drept.`,`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Genunchii ușor îndoiți.`,`Du coatele de-a lungul trunchiului.`]},"towel-row":{name:`Ramat cu prosop`,description:`Tragerea propriului corp cu ajutorul unui prosop fixat de un suport sigur. Antrenează mușchii spatelui și bicepșii fără echipament.`,steps:[`Înfășoară un prosop rezistent în jurul unui suport sigur, la nivelul taliei, și apucă ambele capete.`,`Înclină-te pe spate cu brațele întinse, cu tălpile mai aproape de suport.`,`Trage pieptul spre mâini, ducând coatele înapoi.`,`Întinde încet brațele și revino în poziția de start.`],warnings:[`Fixează prosopul doar de un suport sigur: un stâlp stabil, o balustradă sau mânerul unei uși închise, care se deschide dinspre tine.`,`Verifică dacă prosopul este rezistent și nu îți alunecă din mâini.`],techniqueNotes:[`Ține corpul drept de la cap la călcâie.`,`Cu cât tălpile sunt mai aproape de suport, cu atât exercițiul e mai greu.`]},"inverted-table-row":{name:`Ramat sub masă`,description:`Tracțiune orizontală, culcat sub o masă solidă. Antrenează mușchii spatelui, bicepșii și deltoizii posteriori.`,steps:[`Culcă-te pe spate sub masă, astfel încât pieptul să fie sub marginea blatului.`,`Apucă marginea blatului cu priza la lățimea umerilor.`,`Contractă abdomenul și fesierii, trage pieptul spre marginea mesei.`,`Coboară încet, întinzând complet brațele.`],warnings:[`Folosește doar o masă grea și stabilă, care nu se răstoarnă și îți susține greutatea.`,`Apucă marginea blatului, nu sticla sau elementele fragile.`],techniqueNotes:[`Corpul drept de la umeri la călcâie, bazinul nu cedează.`,`Pentru a-l face mai ușor, îndoaie genunchii și pune tălpile pe podea.`]},"prone-y-t-w-raise":{name:`Ridicări Y-T-W culcat`,description:`Ridicări ale brațelor în trei poziții, culcat pe burtă. Antrenează partea superioară a spatelui și stabilizatorii omoplaților.`,steps:[`Culcă-te pe burtă, cu fruntea deasupra podelei și brațele întinse înainte.`,`Ridică brațele în forma literei Y, menține o secundă și coboară.`,`Depărtează brațele în lateral, în forma literei T, ridică și coboară.`,`Îndoaie coatele în forma literei W, apropie omoplații, ridică și coboară brațele. Aceasta este o repetare.`],warnings:[`Nu da capul pe spate.`,`Oprește exercițiul dacă apare durere la umeri sau gât.`],techniqueNotes:[`Mișcarea pornește de la omoplați, nu din zona lombară.`,`Degetele mari privesc în sus.`]},"reverse-snow-angel":{name:`Înger de zăpadă invers`,description:`Mișcare lină a brațelor de la șolduri spre cap, culcat pe burtă. Antrenează partea superioară a spatelui și mobilitatea umerilor.`,steps:[`Culcă-te pe burtă, cu brațele pe lângă corp și palmele spre șolduri.`,`Ridică brațele de la podea și apropie omoplații.`,`Du încet brațele într-un arc în lateral, până deasupra capului.`,`Pe același drum, adu brațele înapoi spre șolduri, fără să atingi podeaua.`],warnings:[`Nu da capul pe spate.`,`Oprește exercițiul dacă apare durere la umeri sau gât.`],techniqueNotes:[`Ține brațele tot timpul puțin deasupra podelei.`,`Nu arcui zona lombară, fesierii contractați.`]},"leg-press":{name:`Presă pentru picioare la aparat`,description:`Împingerea platformei cu picioarele, șezând. Antrenează cvadricepșii și fesierii fără încărcarea coloanei, potrivit pentru începători.`,steps:[`Așază-te în aparat, cu zona lombară lipită de spătar și tălpile pe platformă, la lățimea umerilor.`,`Eliberează opritoarele și îndoaie încet genunchii până la o adâncime confortabilă.`,`Expirând, întinde picioarele, fără să blochezi complet genunchii.`,`Pune opritoarele la loc după terminarea seriei.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Zona lombară nu se desprinde de spătar.`,`Genunchii merg în direcția degetelor de la picioare.`]},"machine-chest-press":{name:`Presă pentru piept la aparat`,description:`Împingerea mânerelor de la piept, șezând. Învață în siguranță mișcarea de presă și antrenează pieptul, umerii și tricepsul.`,steps:[`Reglează scaunul astfel încât mânerele să fie la nivelul mijlocului pieptului.`,`Apucă mânerele și lipește omoplații de spătar.`,`Expirând, întinde brațele înainte, fără să blochezi complet coatele.`,`Adu încet mânerele înapoi, simțind întinderea pieptului.`],warnings:[`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Umerii nu se ridică spre urechi.`]},"machine-shoulder-press":{name:`Presă pentru umeri la aparat`,description:`Presă verticală, șezând la aparat. Antrenează umerii și tricepsul, cu sprijin pentru spate.`,steps:[`Reglează scaunul astfel încât mânerele să fie la nivelul umerilor.`,`Lipește spatele de spătar și apucă mânerele.`,`Expirând, întinde brațele în sus.`,`Coboară încet mânerele până la nivelul umerilor.`],warnings:[`Oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Nu arcui zona lombară.`]},"seated-cable-row":{name:`Ramat la cablu șezând`,description:`Tragerea orizontală a mânerului de la cablu. Antrenează spatele și deltoizii posteriori și învață apropierea omoplaților.`,steps:[`Așază-te, pune tălpile pe suporturi și apucă mânerul cu spatele drept.`,`Trage mânerul spre abdomen, apropiind omoplații.`,`Oprește-te o clipă în punctul final.`,`Adu încet brațele înainte, fără să rotunjești spatele.`],warnings:[`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Trunchiul aproape nemișcat.`,`Coatele se mișcă de-a lungul corpului.`]},"lat-pulldown-machine":{name:`Tragere la piept la scripete`,description:`Tragerea unei bare late spre piept, șezând. Pregătește pentru tracțiuni și antrenează mușchii dorsali.`,steps:[`Fixează coapsele sub suporturi, apucă bara mai larg decât umerii.`,`Înclină-te ușor pe spate și trage bara spre partea de sus a pieptului.`,`Apropie omoplații și oprește-te o clipă.`,`Adu încet bara în sus.`],warnings:[],techniqueNotes:[`Trage cu coatele, nu cu mâinile.`]},"leg-curl-machine":{name:`Flexii pentru picioare la aparat`,description:`Flexie izolată a picioarelor, culcat sau șezând. Antrenează partea posterioară a coapsei.`,steps:[`Reglează suportul astfel încât să fie deasupra călcâielor.`,`Expirând, îndoaie picioarele, aducând călcâiele spre fese.`,`Oprește-te o clipă în punctul de sus.`,`Întinde încet picioarele.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Bazinul nu se desprinde de bancă.`]},"leg-extension-machine":{name:`Extensii pentru picioare la aparat`,description:`Extensie izolată a picioarelor, șezând. Antrenează cvadricepșii.`,steps:[`Reglează spătarul și suportul deasupra gambelor.`,`Expirând, întinde picioarele.`,`Oprește-te o clipă în punctul de sus.`,`Coboară încet picioarele.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Mișcările sunt line, fără smucituri.`]},"cable-triceps-pushdown":{name:`Extensii pentru triceps la cablu`,description:`Extensia brațelor în jos, la scripetele de sus. Antrenează izolat tricepsul.`,steps:[`Stai în fața scripetelui, apucă mânerul, cu coatele lipite de corp.`,`Expirând, întinde brațele în jos.`,`Oprește-te o clipă jos.`,`Adu încet mânerul înapoi la nivelul pieptului.`],warnings:[],techniqueNotes:[`Coatele nu se mișcă.`]},"cable-biceps-curl":{name:`Flexii pentru biceps la scripetele de jos`,description:`Flexia brațelor, în picioare, lângă scripetele de jos. Antrenează izolat bicepsul.`,steps:[`Stai în fața scripetelui de jos, apucă mânerul cu palmele în sus.`,`Expirând, îndoaie brațele spre umeri.`,`Oprește-te o clipă sus.`,`Întinde încet brațele.`],warnings:[],techniqueNotes:[`Coatele lipite de corp, trunchiul nemișcat.`]},"cable-face-pull":{name:`Face pull la cablu`,description:`Tragerea mânerului-frânghie spre nivelul feței. Întărește deltoizii posteriori și mușchii dintre omoplați, utilă pentru postură.`,steps:[`Fixează frânghia la scripete, la nivelul feței, și fă un pas înapoi.`,`Trage frânghia spre față, depărtând coatele în lateral.`,`Apropie omoplații și oprește-te o clipă.`,`Adu încet brațele înainte.`],warnings:[],techniqueNotes:[`Greutatea ușoară, mișcarea controlată.`]},"cable-woodchop":{name:`Woodchop la cablu`,description:`Rotirea diagonală a trunchiului cu mânerul de la cablu. Antrenează oblicii și învață transmiterea forței prin trunchi.`,steps:[`Stai cu o parte spre scripete, apucă mânerul cu ambele mâini.`,`Trage mânerul în diagonală, în jos, rotind trunchiul.`,`Ține brațele aproape drepte, rotește cutia toracică.`,`Adu încet mânerul înapoi și repetă, apoi schimbă partea.`],warnings:[`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Mișcă trunchiul, nu doar brațele.`]},"barbell-bench-press":{name:`Presă cu bara culcat`,description:`Presa clasică cu bara pe o bancă orizontală. Exercițiul principal pentru piept, umeri și triceps.`,steps:[`Întinde-te pe bancă, cu tălpile pe podea, omoplații uniți și ochii sub bară.`,`Scoate bara și coboară-o spre mijlocul pieptului.`,`Expirând, împinge bara în sus până îți întinzi brațele.`,`Pune bara în stativ când termini seria.`],warnings:[`Nu apăsa bara fără asigurare la sală și oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Folosește un asigurator sau opritoare.`,`Încheieturile deasupra coatelor.`]},"barbell-bent-over-row":{name:`Ramat cu bara în aplecare`,description:`Tragerea barei spre abdomen, în aplecare. Antrenează întreg spatele, deltoizii posteriori și bicepsul.`,steps:[`Stai cu tălpile la lățimea umerilor, apucă bara cu priza puțin mai largă decât umerii.`,`Apleacă-te înainte cu spatele drept, cu genunchii ușor îndoiți.`,`Trage bara spre partea de jos a abdomenului.`,`Coboară încet bara, fără să rotunjești spatele.`],warnings:[`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Spatele drept pe toată durata mișcării.`]},"barbell-overhead-press":{name:`Presă cu bara în picioare`,description:`Presa barei deasupra capului, în picioare. Dezvoltă forța umerilor și a părții superioare a spatelui și cere un trunchi stabil.`,steps:[`Ia bara la nivelul claviculelor, cu priza puțin mai largă decât umerii.`,`Contractă abdomenul și fesierii și, expirând, împinge bara în sus.`,`La final, capul trece puțin înainte, iar bara este deasupra mijlocului tălpii.`,`Coboară încet bara la nivelul claviculelor.`],warnings:[`Oprește exercițiul dacă apare durere la umeri sau în zona lombară.`],techniqueNotes:[`Nu arcui zona lombară.`]},"barbell-romanian-deadlift":{name:`Îndreptări românești cu bara`,description:`Îndreptare cu picioare aproape drepte. Antrenează partea posterioară a coapsei și fesierii și învață mișcarea cu împingerea șoldurilor înapoi.`,steps:[`Stai cu bara în mâini, cu genunchii ușor îndoiți.`,`Împinge șoldurile înapoi, ducând bara de-a lungul picioarelor.`,`Coboară-o sub nivelul genunchilor, păstrând spatele drept.`,`Expirând, revino în poziția de start, împingând șoldurile înainte.`],warnings:[`Oprește exercițiul dacă apare durere în zona lombară.`],techniqueNotes:[`Mișcarea pornește de la șolduri, nu de la spate.`]},"treadmill-incline-walk":{name:`Mers pe bandă cu înclinare`,description:`Mers rapid pe banda de alergare înclinată. Efort cardio fără impact pentru rezistență și picioare.`,steps:[`Setează o înclinare de 4–8% și un mers rapid confortabil.`,`Ține trunchiul drept, fără să te sprijini de balustradă.`,`Mergi într-un ritm constant timpul necesar.`,`La final, scade viteza și înclinarea pentru recuperare.`],warnings:[],techniqueNotes:[`Respirația rămâne uniformă, poți vorbi în fraze scurte.`]},"easy-run-intervals":{name:`Alergare ușoară pe intervale`,description:`Alternarea alergării calme cu mersul. Dezvoltă rezistența inimii și a respirației fără efort brusc.`,steps:[`Încălzește-te un minut cu mers rapid.`,`Aleargă într-un ritm confortabil timpul stabilit.`,`Treci la mers pentru recuperare.`,`Repetă alternanța în funcție de numărul de serii.`],warnings:[`Oprește alergarea dacă apare durere la glezne sau genunchi.`],techniqueNotes:[`Ritmul îți permite să respiri pe nas sau să vorbești în fraze scurte.`]},"sprint-intervals":{name:`Accelerări de sprint`,description:`Accelerări scurte la viteză maximă, cu pauză completă. Dezvoltă puterea și rezistența în viteză.`,steps:[`Încălzește-te bine și fă câteva accelerări ușoare.`,`Accelerează la aproximativ 90% din viteza maximă.`,`După accelerare, revino la mers și recuperează-te complet.`,`Repetă în funcție de numărul de serii.`],warnings:[`Nu face exercițiul pe o suprafață alunecoasă și oprește-te dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Înclină trunchiul înainte și lucrează cu brațele.`]},"brisk-walk-intervals":{name:`Mers rapid pe intervale`,description:`Alternarea mersului rapid cu cel calm, în aer liber. Potrivit pentru început și pentru recuperare.`,steps:[`Mergi calm un minut pentru încălzire.`,`Mergi rapid, balansând brațele îndoite.`,`Treci la un pas calm pentru recuperare.`,`Repetă alternanța.`],warnings:[],techniqueNotes:[`Pas rapid: respirația e accelerată, dar poți vorbi.`]},"walking-lunge":{name:`Fandări în mers`,description:`Fandări cu înaintare. Antrenează picioarele și fesierii și învață echilibrul.`,steps:[`Stai drept, cu mâinile pe șolduri sau pe lângă corp.`,`Fă un pas larg înainte și coboară, îndoind ambii genunchi la 90°.`,`Împinge cu piciorul din față și adu piciorul din spate lângă cel din față.`,`Continuă, alternând picioarele.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Genunchiul din față deasupra gleznei.`]},"bear-crawl":{name:`Târâre de urs`,description:`Deplasare în patru puncte de sprijin, cu genunchii ridicați. Întărește umerii, trunchiul și picioarele și dezvoltă coordonarea.`,steps:[`Stai pe palme și pe tălpi, cu genunchii la 5 cm de sol.`,`Mută simultan înainte brațul și piciorul opus.`,`Ține spatele drept și bazinul jos.`,`Deplasează-te timpul stabilit, apoi înapoi, în același mod.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi.`],techniqueNotes:[`Mișcările sunt lente și controlate.`]},"broad-jump":{name:`Săritură în lungime de pe loc`,description:`Săritură explozivă înainte, de pe ambele picioare. Dezvoltă puterea picioarelor și coordonarea.`,steps:[`Stai cu tălpile la lățimea umerilor, cu brațele duse înapoi.`,`Împinge, balansând brațele înainte, și sari cât mai departe.`,`Aterizează moale, cu genunchii îndoiți.`,`Oprește-te, îți recapeți echilibrul și repetă.`],warnings:[`Nu face exercițiul pe o suprafață alunecoasă și oprește-te dacă apare durere la genunchi.`],techniqueNotes:[`Aterizare moale, pe toată talpa.`]},"skater-jumps":{name:`Sărituri de patinator`,description:`Sărituri laterale de pe un picior pe altul. Antrenează echilibrul, picioarele și rezistența.`,steps:[`Stai pe un picior, cu celălalt dus în spate.`,`Sari în lateral pe celălalt picior, balansând brațele.`,`Oprește-te o clipă, menținându-ți echilibrul.`,`Sari înapoi și continuă timpul stabilit.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi sau glezne.`],techniqueNotes:[`Aterizare moale, genunchiul în spatele vârfului.`]},"shuttle-run":{name:`Alergare de navetă`,description:`Alergare între două puncte, cu schimbarea direcției. Dezvoltă viteza de reacție și rezistența.`,steps:[`Marchează două puncte la 3 m unul de altul.`,`Aleargă până la al doilea punct și atinge pământul cu mâna.`,`Întoarce-te rapid și aleargă înapoi.`,`Repetă timpul stabilit.`],warnings:[`Nu face exercițiul pe o suprafață alunecoasă.`],techniqueNotes:[`Întoarce-te cu genunchii îndoiți, piciorul nu se duce prea departe.`]},"stair-climb":{name:`Urcat pe scări`,description:`Urcare rapidă pe scări sau pe o pantă abruptă. Cardio și antrenament pentru picioare și fesieri.`,steps:[`Stai la baza scărilor sau a pantei.`,`Urcă într-un pas rapid, punând pe treaptă toată talpa.`,`Urcă timpul stabilit, apoi coboară încet.`,`Repetă în funcție de numărul de serii.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Coborârea e calmă, ține-te de balustradă dacă e nevoie.`]},"park-bench-step-up":{name:`Urcare pe banca din parc`,description:`Urcarea pe o bancă stabilă, pe un picior. Antrenează cvadricepșii și fesierii.`,steps:[`Verifică dacă banca e stabilă și stai în fața ei.`,`Pune un picior pe bancă și urcă, întinzând piciorul.`,`Coboară încet, controlând mișcarea.`,`Termină seria și schimbă piciorul.`],warnings:[`Oprește exercițiul dacă apare durere la genunchi.`],techniqueNotes:[`Împinge cu piciorul de pe bancă, nu te ajuta de pe pământ.`]},"park-bench-incline-push-up":{name:`Flotări cu mâinile pe bancă`,description:`Flotări cu mâinile sprijinite pe o bancă. Variantă ușurată pentru piept, umeri și triceps.`,steps:[`Pune palmele pe marginea unei bănci stabile, cu corpul într-o linie.`,`Îndoaie coatele și coboară pieptul spre bancă.`,`Expirând, împinge până îți întinzi brațele.`,`Ține trunchiul contractat pe toată durata mișcării.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi.`],techniqueNotes:[`Coatele în unghi de aproximativ 45° față de trunchi.`]},"australian-pull-up":{name:`Tracțiuni australiene`,description:`Tragerea corpului spre o bară joasă, culcat sub ea. Antrenează spatele și bicepsul, mai ușoară decât tracțiunile.`,steps:[`Stai sub o bară joasă și rezistentă și apucă-o cu priza mai largă decât umerii.`,`Întinde corpul într-o linie dreaptă, cu călcâiele pe pământ.`,`Trage pieptul spre bară, apropiind omoplații.`,`Coboară încet, până când brațele sunt aproape drepte.`],warnings:[`Asigură-te că bara este rezistentă și oprește exercițiul dacă apare durere la umeri.`],techniqueNotes:[`Corpul rămâne drept, bazinul nu cedează.`]},"outdoor-plank-shoulder-taps":{name:`Plank cu atingeri de umăr`,description:`Plank cu atingeri alternative ale umărului. Antrenează trunchiul și stabilitatea umerilor.`,steps:[`Adoptă poziția de plank cu brațele întinse, cu tălpile puțin mai late decât umerii.`,`Atinge cu mâna dreaptă umărul stâng, fără să legeni bazinul.`,`Adu mâna înapoi și atinge cu cealaltă.`,`Continuă alternanța timpul stabilit.`],warnings:[`Oprește exercițiul dacă apare durere la încheieturi.`],techniqueNotes:[`Bazinul aproape că nu se mișcă.`]}};export{n as burpee,t as default,a as plank,r as superman};